+			//Send8(_hid_protocol);	// TODO
+				return true;
+			}
+		}
+		
+		if (REQUEST_HOSTTODEVICE_CLASS_INTERFACE == requestType)
+		{
+			if (HID_SET_PROTOCOL == r)
+			{
+				_hid_protocol = setup.wValueL;
+				return true;
